const {test}=require('node:test');const assert=require('node:assert/strict');const C=require('../src/core.js'),M=require('../src/character-model.js');
test('prévia permite adicionar e desfazer sem alterar personagem ou recursos',()=>{const p=C.fresh(),before=JSON.stringify(p),d=M.begin(p);assert.equal(M.adjust(p,d,'forca',-1),false);assert.equal(M.adjust(p,d,'forca',1),true);assert.equal(M.adjust(p,d,'vitalidade',1),true);assert.equal(M.remaining(d),3);assert.equal(M.preview(p,d).attrs.forca,6);assert.equal(C.stats(M.preview(p,d)).hp,320);assert.equal(JSON.stringify(p),before);assert.equal(M.adjust(p,d,'forca',-1),true);assert.equal(M.remaining(d),4);assert.equal(JSON.stringify(p),before);});
test('limites impedem negativos, atributos desconhecidos e gasto acima do saldo',()=>{const p=C.fresh(),d=M.begin(p);for(let i=0;i<5;i++)assert.ok(M.adjust(p,d,'destreza',1));assert.equal(M.adjust(p,d,'magia',1),false);assert.equal(M.adjust(p,d,'invalido',1),false);assert.equal(M.adjust(p,d,'forca',2),false);assert.ok(M.adjust(p,d,'destreza',-1));assert.ok(M.adjust(p,d,'magia',1));assert.equal(M.remaining(d),0);assert.ok(M.apply(p,d));assert.equal(p.unspent,0);assert.equal(p.attrs.destreza,9);assert.equal(p.attrs.magia,6);});
test('aplicar é atômico e único, mantendo a quantidade de vida/mana perdida',()=>{const p=C.fresh();p.hp=250;p.mp=80;const d=M.begin(p);for(const k of ['forca','vitalidade','magia'])assert.ok(M.adjust(p,d,k,1));assert.ok(M.apply(p,d));assert.equal(p.unspent,2);assert.equal(p.hp,270);assert.equal(p.mp,90);assert.equal(C.stats(p).hp,320);assert.equal(C.stats(p).mp,110);const applied=JSON.stringify(p);assert.equal(M.apply(p,d),false);assert.equal(JSON.stringify(p),applied);assert.equal(C.validateSave(p).attrs.vitalidade,6);});
test('prévia vencida por nível ou saldo atualizado é recusada sem mutação parcial',()=>{for(const change of [p=>C.allocate(p,'forca'),p=>C.gainXP(p,C.xpFor(p.level))]){const p=C.fresh(),d=M.begin(p);M.adjust(p,d,'magia',1);change(p);const before=JSON.stringify(p);assert.equal(M.apply(p,d),false);assert.equal(JSON.stringify(p),before);assert.equal(M.preview(p,d),null);}});
test('prévia vazia ou adulterada é recusada sem alterar o personagem',()=>{const p=C.fresh(),before=JSON.stringify(p);assert.equal(M.apply(p,M.begin(p)),false);for(const bad of [null,{}, {...M.begin(p),added:{forca:-1,destreza:0,magia:0,vitalidade:0}},{...M.begin(p),added:{forca:1.5,destreza:0,magia:0,vitalidade:0}},{...M.begin(p),added:{forca:99,destreza:0,magia:0,vitalidade:0}}])assert.equal(M.apply(p,bad),false);assert.equal(JSON.stringify(p),before);});
test('bônus de talentos não podem ser retirados e aparecem na prévia',()=>{const p=C.fresh();p.tree=['f1'];const d=M.begin(p);assert.equal(C.stats(M.preview(p,d)).forca,10);assert.equal(M.adjust(p,d,'forca',-1),false);assert.ok(M.adjust(p,d,'forca',1));assert.ok(M.adjust(p,d,'forca',-1));assert.equal(C.stats(M.preview(p,d)).forca,10);assert.equal(p.attrs.forca,5);});
